请把下面这个 TypeScript 函数重构得更清晰，但不要新建 DDD 目录，也不要引入类。

```typescript
export function calc(items: { price: number; quantity: number; disabled?: boolean }[], vip: boolean): number {
  let total = 0;
  for (const item of items) {
    if (!item.disabled) {
      total += item.price * item.quantity;
    }
  }
  if (vip) {
    total = total * 0.9;
  }
  return total;
}
